  "Analysiert deinen digitalen Browser-Fingerabdruck. Cookies löschen reicht nicht – WebGL, Audio-Chips und Canvas-Rendering verraten deine exakte Hardware-Signatur.": {
    "en": "Analyzes your digital browser fingerprint. Deleting cookies is not enough – WebGL, audio chips and Canvas rendering expose your exact hardware signature.",
    "ru": "Анализирует цифровой отпечаток браузера. Очистки куки недостаточно – WebGL, аудиочипы и Canvas раскрывают точную сигнатуру вашего оборудования.",
    "es": "Analiza la huella digital de tu navegador. Borrar cookies no basta: WebGL, chips de audio y Canvas revelan la firma exacta de tu hardware.",
    "it": "Analizza l'impronta digitale del tuo browser. Eliminare i cookie non basta: WebGL, chip audio e Canvas rivelano la tua esatta firma hardware.",
    "zh": "深度剖析您的浏览器硬件数字指纹。仅仅清除 Cookie 远不足够——WebGL、音频解码芯片与 Canvas 渲染会彻底暴露出您设备的独有硬件特征。",
    "ja": "ブラウザのデジタルフィンガープリントを診断。Cookie削除だけでは不十分です。WebGL、音響チップ、Canvas描画がハードウェア固有の特徴を露呈します。",
    "fr": "Analyse votre empreinte numérique de navigateur. Supprimer les cookies ne suffit pas : WebGL, puces audio et rendu Canvas révèlent votre signature matérielle."
  },
