  "Lokaler Leak-Scanner fuer ZIPs, Projektordner, .env-Dateien und Code. Secrets werden nur maskiert angezeigt und verlassen den Browser nicht.": {
    "en": "Local leak detector for ZIPs, repositories, .env files and source code. Secrets are masked and never leave the browser.",
    "ru": "Локальный сканер утечек для архивов ZIP, репозиториев, .env и кода. Найденные секреты маскируются и не покидают браузер.",
    "es": "Escáner de fugas local para ZIPs, proyectos, archivos .env y código. Los secretos se muestran enmascarados y no salen del navegador.",
    "it": "Scanner di fughe locale per ZIP, cartelle, file .env e codice. I segreti sono mascherati e non lasciano il browser.",
    "zh": "本地机密凭据泄漏扫描器。全面检查 ZIP 归档、项目源码与 .env 配置文件，敏感凭证仅脱敏展示，绝不泄漏出当前浏览器。",
    "ja": "ZIP、フォルダ、環境変数(.env)、コードの機密漏洩ローカル検出器。認証情報はマスク表示され、端末外に一切送信されません。",
    "fr": "Scanner local de fuites pour ZIP, dossiers, fichiers .env et code. Les secrets sont masqués et ne quittent jamais le navigateur."
  },
