  "Deep-Packet Network Analysis. Analysiere .har (HTTP Archive) Traffic-Logs lokal im RAM. Enttarne Tracker, analysiere Payloads und identifiziere Data-Leaks (Cookies/Tokens).": {
    "en": "Deep-packet network analysis. Parse .har traffic dumps locally in RAM. Unmask trackers, inspect payloads and identify leaked session cookies or tokens.",
    "ru": "Глубокий анализ дампов сетевого трафика. Разбор логов .har прямо в памяти. Обнаружение трекеров, анализ полезной нагрузки и поиск утечек сессий.",
    "es": "Análisis de red profundo. Analiza volcados .har localmente en RAM. Desenmascara rastreadores, analiza cargas útiles y detecta fugas de datos.",
    "it": "Analisi di rete approfondita. Analizza i log .har localmente nella RAM. Smaschera i tracker, ispeziona i payload e rileva fughe di dati.",
    "zh": "深度网络抓包协议审查。在本地内存中直接解析 .har 流量归档，快速识别隐秘追踪探针、审查请求载荷并截获外泄的 Cookie 与令牌凭据。",
    "ja": "高度なネットワーク解析。ブラウザRAM内で.harファイルを安全に構文解析。トラッカーを特定し、Cookieや認証トークンの漏洩を検知。",
    "fr": "Analyse réseau en profondeur. Analysez les journaux .har en local dans la RAM. Démasquez les traceurs et identifiez les fuites de données."
  },
