  "Füge mehrere PDFs zu einem einzigen Master-Dokument zusammen. 100% lokal im Browser-RAM. Zero Trust, maximale Vertraulichkeit für Verträge und Dokumente.": {
    "en": "Merge multiple PDFs into a single master document. 100% locally in browser RAM. Zero Trust, maximum confidentiality for contracts and sensitive files.",
    "ru": "Объединяйте несколько PDF в единый мастер-документ. 100% локально в RAM. Zero-Trust, максимальная конфиденциальность для договоров и документов.",
    "es": "Une varios PDF en un único documento maestro. 100% local en RAM. Confianza Cero, máxima confidencialidad para contratos y documentos.",
    "it": "Unisci più PDF in un unico documento master. 100% locale nella RAM. Zero Trust, massima riservatezza per contratti e documenti riservati.",
    "zh": "将多份独立 PDF 拼接合并为单个主控文档。100% 运行于浏览器 RAM 中。零信任准则，为商业合同与机密文档提供最高安全屏障。",
    "ja": "複数のPDFファイルを1つのマスター文書に統合。100%ブラウザRAM内で完結。契約書や機密文書のための最高水準プライバシー保護。",
    "fr": "Fusionnez plusieurs PDF en un document maître unique. 100% en local dans la RAM. Confidentialité maximale pour contrats et documents sensibles."
  },
