    "zh": "可视化多阶密码学流水线。以搭积木方式自由拼接 Base64、Hex、AES 与散列算法的执行管道。100% 纯前端运行。",
    "ja": "ビジュアル暗号ラボ。暗号化・復号化・多段エンコードのパイプラインを視覚的にリアルタイム構築。CryptoJSによる完全クライアントサイド実行。",
