  "Deep File Inspector. Analysiert rohe Binärdaten im sicheren Sandbox-Modus. Detektiert versteckte Malware, Anomalien in Datei-Headern (Magic Numbers) und extrahiert ASCII-Strings.": {
    "en": "Deep file inspector. Inspects raw binary byte streams in a sandbox. Detects anomalies in headers (magic bytes) and extracts ASCII strings.",
    "ru": "Глубокий анализ файлов. Исследует бинарные потоки байтов в песочнице. Находит аномалии в заголовках (Magic Bytes) и извлекает строки ASCII.",
    "es": "Inspector binario profundo. Analiza flujos de bytes sin procesar en una sandbox segura. Detecta anomalías en cabeceras y extrae cadenas ASCII.",
    "it": "Ispettore binario avanzato. Analizza flussi di byte grezzi in una sandbox sicura. Rileva anomalie negli header ed estrae stringhe ASCII.",
    "zh": "二进制底层逆向取证探针。在独立安全沙盒中检视裸字节流，深度识别文件头部魔数 (Magic Bytes)、挖掘可读 ASCII 字符串并识别伪装拓展名。",
    "ja": "高機能バイナリ解析ツール。安全なサンドボックス内でバイト列を精査。マジックナンバーの異常検知や可読ASCII文字列を抽出。",
    "fr": "Inspecteur de fichiers en profondeur. Analyse les flux binaires bruts dans un bac à sable sécurisé. Détecte les anomalies d'en-têtes et extrait les chaînes ASCII."
  },
