    "it": "Scanner di sicurezza per repository. Esamina cartelle locali o ZIP alla ricerca di chiavi API e password prima del commit. 100% client-side.",
    "zh": "代码仓库提交前泄漏阻断器。全面扫描本地工程目录或代码压缩包，阻止意外暂存的 API 密钥、数据库凭证与私钥流出。100% 离线保护。",
    "ja": "Gitリポジトリセキュリティ監査。コミット前にローカルフォルダやZIPを走査し、混入したAPIキーや秘密鍵を水際阻止。100%安全。",
