    "zh": "智能电表能耗分析与电器设备矩阵。即时测算各类电器功率负荷与年度用电开支。安全纯本地导入电力供应商导出的历史 CSV 账单。",
    "ja": "スマートメーター解析 ＆ 機器マトリクス。電力消費量と電気料金をリアルタイム試算。電力会社のCSVデータを安全にオフライン分析。",
