  "Die Audiosignale werden in Echtzeit lokal in deinem Browser berechnet. Es fließen keine Daten aus dem Netzwerk.": {
    "en": "Audio waveforms are synthesized in real time locally in your browser. Zero data transferred over the network.",
    "ru": "Звуковые волны генерируются в реальном времени локально в браузере. Данные по сети не передаются.",
    "es": "Las señales de audio se calculan en tiempo real en tu navegador. Cero datos transferidos por la red.",
    "it": "I segnali audio sono calcolati in tempo reale nel browser. Nessun dato viene trasmesso in rete.",
    "zh": "所有雨声与白噪音信号均基于数学算法在本地浏览器中即时实时渲染。全程无任何音频网络数据消耗。",
    "ja": "音響シグナルはブラウザ内でリアルタイムに数学合成されます。ネットワーク通信は一切発生しません。",
    "fr": "Les signaux audio sont calculés en direct dans votre navigateur. Aucune donnée ne transite par le réseau."
  },
