  "Echtzeit-Telemetrie deines mentalen Zustands. Analysiere Stress-Level, Fokus-Kapazität und neuronale Erschöpfung durch bio-metrische Selbsteinschätzung.": {
    "en": "Real-time telemetry of your mental state. Evaluate stress levels, focus capacity and fatigue through self-assessment metrics.",
    "ru": "Телеметрия ментального состояния в реальном времени. Оценка стресса, концентрации и утомления через самодиагностику.",
    "es": "Telemetría en tiempo real de tu estado mental. Evalúa niveles de estrés, capacidad de foco y fatiga cognitiva.",
    "it": "Telemetria in tempo reale del tuo stato mentale. Valuta stress, capacità di concentrazione e affaticamento neurale.",
    "zh": "大脑认知状态实时遥测中枢。通过交互式反应指标精准评估当前心理压力负荷、注意力留存率与神经疲劳程度。",
    "ja": "精神状態のリアルタイム・テレメトリ。生体セルフチェックを通じてストレス度、集中維持力、疲労度を客観分析。",
    "fr": "Télémétrie en temps réel de votre état mental. Évaluez le niveau de stress, la capacité de concentration et la fatigue."
  },
