    "de": "Visuelle Phantom-Kommunikation. Verstecke AES-256 verschlüsselte Nachrichten in den tiefsten Bit-Ebenen (LSB) unscheinbarer Bilder. 100% Offline-Sicherheit.",
    "en": "Visual covert communication. Hide AES-256 encrypted messages inside lowest bit planes (LSB) of innocuous images. 100% offline security.",
    "ru": "Скрытая визуальная связь. Прячьте AES-256 зашифрованные данные в младших битах (LSB) обычных картинок. 100% офлайн.",
